20	import {
21	    createHashMap,
22	    defaults,
23	    each, eqNaN, isArray, isObject, isString
24	} from 'zrender/src/core/util';
25	import Point from 'zrender/src/core/Point';
26	import OrdinalMeta from '../../data/OrdinalMeta';
27	import { NullUndefined, OrdinalNumber } from '../../util/types';
28	import Ordinal from '../../scale/Ordinal';
29	import {
30	    MatrixDimensionModel, MatrixDimensionCellOption, MatrixDimensionCellLooseOption,
31	    MatrixDimensionLevelOption,
32	    MatrixCoordValueOption,
33	} from './MatrixModel';
34	import { WH, XY } from '../../util/graphic';
35	import { ListIterator } from '../../util/model';
36	import { RectLike } from 'zrender/src/core/BoundingRect';
37	import {
38	    createNaNRectLike, setDimXYValue, MatrixCellLayoutInfoType
39	} from './matrixCoordHelper';
40	import { error } from '../../util/log';
41	import { mathMax } from '../../util/number';
42	
43	
44	export interface MatrixCellLayoutInfo {
45	    type: MatrixCellLayoutInfoType;
46	    // Represents col/row, serves as both id and locator.
47	    // For a `MatrixDimensionCell`:
48	    //  it is `setDimXYValue(new Point(), dimIdx, firstLeafLocator, level - _levels.length)`.
49	    //  e.g., `id[dimIdx]` is `0` or `1` or `2` or `3` if there are at most `4` leaves in the tree.
50	    // For a `MatrixDimensionLevelInfo`:
51	    //  it is `setDimXYValue(new Point(), dimIdx, 0, level - _levels.length)`
52	    //  e.g., `id[1 - dimIdx]` is `-3` or `-2` or `-1` if the tree has `3` levels.
53	    // If negative, locate to corner cells; otherwise, locate to body cells.
54	    id: Point;
55	    // By pixel. Computed left-top x (for x dimension) or y (for y dimension).
56	    // Used to locate.
57	    xy: number;
58	    // By pixel. Computed height (for x dimension) or width (for y dimension).
59	    // Used to locate.
60	    wh: number;
61	    dim: MatrixDim;
62	}
63	
64	
65	export type MatrixXYLocator = MatrixCellLayoutInfo['id']['x'] | MatrixCellLayoutInfo['id']['y'];
66	/**
67	 * [[xmin, xmax], [ymin, ymax]]
68	 * For each internal value, be NaN if invalid or out of boundary (never be null/undefined),
69	 * otherwise must be valid locators.
70	 * @see parseCoordRangeOption
71	 * @see resetXYLocatorRange
72	 */
73	export type MatrixXYLocatorRange = MatrixXYLocator[][] & {__brand: 'MatrixXYLocatorRange'};
74	/**
75	 * [[xmin, xmax], [ymin, ymax]], be `NullUndefined` if illegal.
76	 */
77	export type MatrixXYCellLayoutInfoRange = (MatrixCellLayoutInfo | NullUndefined)[][];
78	
79	export interface MatrixDimensionCell extends MatrixCellLayoutInfo {
80	    // Computed col/row span. Always exists and >= 1.
81	    // `span[XY[dimIdx]]` is actually the leaves count of this subtree.
82	    span: Point;
83	    // Start from 0, tree depth.
84	    level: number;
85	    // It is both `MatrixXYLocator` and `OrdinalNumber` and _cell[index].
86	    firstLeafLocator: MatrixXYLocator;
87	    // Used to fatch its raw value by `matrixDim.getOrdinalMeta().category[ordinal]`,
88	    // or feach cell by `_cells[ordinal]`.
89	    // The ordinal of the leaf nodes is the same as `id.getOnDim(0)` for quick query,
90	    // but not the same for non-leaf nodes.
91	    ordinal: OrdinalNumber;
92	    // Normalized raw option of `matrix.x/y.data[i]`, not include any parents option.
93	    // Never be NullUndefined
94	    option: MatrixDimensionCellOption;
95	    // The layout rect for rendering. Available after matrix coordinate system resizing.
96	    rect: RectLike;
97	}
98	
99	/**
100	 * Computed properties of a certain tree level.
101	 * In most cases this is used to describe level size or locate corner cells.
102	 */
103	export interface MatrixDimensionLevelInfo extends MatrixCellLayoutInfo {
104	    // The raw option of `matrix.levels[i]`
105	    option: MatrixDimensionLevelOption | NullUndefined;
106	}
107	
108	export type MatrixDimPair = {
109	    x: MatrixDim;
110	    y: MatrixDim;
111	};
112	
113	/**
114	 * Lifetime: the same with `MatrixModel`, but different from `coord/Matrix`.
115	 */
116	export class MatrixDim {
117	    // Use it to visit `cell.id` and `cell.span`
118	    readonly dim: 'x' | 'y';
119	    // Must be `0 | 1`, corresponding to 'x' | 'y'
120	    readonly dimIdx: number;
121	
122	    // Under the current definition, every leave corresponds a unit cell,
123	    // and leaves can serve as the locator of cells.
124	    // Therefore make sure:
125	    //  - The first `_leavesCount` elements in `_cells` are leaves.
126	    //  - `_cells[leaf.id[XY[this.dimIdx]]]` is the leaf itself.
127	    //  - Leaves of each subtree are placed together, that is, the leaves of a dimCell are:
128	    //    `this._cells.slice(dimCell.firstLeafLocator, dimCell.span[XY[this.dimIdx]])`
129	    private _cells: MatrixDimensionCell[] = [];
130	
131	    // Can be visited by `_levels[cell.level]` or `_levels[cell.id[1 - dimIdx] + _levels.length]`.
132	    // Items are never be null/undefined after initialized.
133	    private _levels: MatrixDimensionLevelInfo[] = [];
134	
135	    private _leavesCount: number;
136	
137	    private _model: MatrixDimensionModel;
138	    private _ordinalMeta: OrdinalMeta;
139	    // Only for uniformly parsing.
140	    private _scale: Ordinal;
141	
142	    private _uniqueValueGen: ReturnType<typeof createUniqueValueGenerator>;
143	
144	    constructor(dim: 'x' | 'y', dimModel: MatrixDimensionModel) {
145	        this.dim = dim;
146	        this.dimIdx = dim === 'x' ? 0 : 1;
147	        this._model = dimModel;
148	
149	        this._uniqueValueGen = createUniqueValueGenerator(dim);
150	
151	        let dimModelData = dimModel.get('data', true);
152	        if (dimModelData != null && !isArray(dimModelData)) {
153	            if (__DEV__) {
154	                error(`Illegal echarts option - matrix.${this.dim}.data must be an array if specified.`);
155	            }
156	            dimModelData = [];
157	        }
158	        if (dimModelData) {
159	            this._initByDimModelData(dimModelData);
160	        }
161	        else {
162	            this._initBySeriesData();
163	        }
164	    }
165	
166	    private _initByDimModelData(dimModelData: MatrixDimensionCellLooseOption[]) {
167	        const self = this;
168	        const _cells = self._cells;
169	        const _levels = self._levels;
170	        const sameLocatorCellsLists: MatrixDimensionCell[][] = []; // Save for sorting.
171	        let _cellCount = 0;
172	
173	        self._leavesCount = traverseInitCells(dimModelData, 0, 0);
174	
175	        postInitCells();
176	
177	        return;
178	
179	        function traverseInitCells(
180	            dimModelData: MatrixDimensionCellLooseOption[] | NullUndefined,
181	            firstLeafLocator: number,
182	            level: number
183	        ): number {
184	            let totalSpan = 0;
185	            if (!dimModelData) {
186	                return totalSpan;
187	            }
188	
189	            each(dimModelData, (option, optionIdx) => {
190	                let invalidOption = false;
191	                let cellOption: MatrixDimensionCell['option'];
192	                if (isString(option)) {
193	                    cellOption = {value: option};
194	                }
195	                else if (isObject(option)) {
196	                    cellOption = option;
197	                    if (option.value != null && !isString(option.value)) {
198	                        invalidOption = true;
199	                        cellOption = {value: null};
200	                    }
201	                }
202	                else {
203	                    cellOption = {value: null};
204	                    if (option != null) {
205	                        invalidOption = true;
206	                    }
207	                }
208	
209	                if (invalidOption) {
210	                    if (__DEV__) {
211	                        error(`Illegal echarts option - matrix.${self.dim}.data[${optionIdx}]`
212	                            + ' must be `string | {value: string}`.'
213	                        );
214	                    }
215	                }
216	
217	                const cell: MatrixDimensionCell = {
218	                    type: MatrixCellLayoutInfoType.nonLeaf, // Update to leaf later if it's a leaf.
219	                    ordinal: NaN, // Set it later.
220	                    level,
221	                    firstLeafLocator,
222	                    id: new Point(), // Set it in `_initCellsId`.
223	                    span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
224	                    option: cellOption,
225	                    xy: NaN,
226	                    wh: NaN,
227	                    dim: self,
228	                    rect: createNaNRectLike(),
229	                };
230	                _cellCount++;
231	                (sameLocatorCellsLists[firstLeafLocator]
232	                    || (sameLocatorCellsLists[firstLeafLocator] = [])
233	                ).push(cell);
234	
235	                if (!_levels[level]) {
236	                    // Create a level only if at least one cell exists.
237	                    _levels[level] = {
238	                        type: MatrixCellLayoutInfoType.level,
239	                        xy: NaN, wh: NaN, option: null, id: new Point(), dim: self
240	                    };
241	                }
242	
243	                const childrenSpan = traverseInitCells(
244	                    cellOption.children, firstLeafLocator, level + 1
245	                );
246	                const subSpan = Math.max(1, childrenSpan);
247	                cell.span[XY[self.dimIdx]] = subSpan;
248	
249	                totalSpan += subSpan;
250	                firstLeafLocator += subSpan;
251	            });
252	
253	            return totalSpan;
254	        }
255	
256	        function postInitCells() {
257	            // Sort to make sure the leaves are at the beginning, so that
258	            // they can be used as the locator of body cells.
259	            const categories: (string | NullUndefined)[] = [];
260	            while (_cells.length < _cellCount) {
261	                for (let locator = 0; locator < sameLocatorCellsLists.length; locator++) {
262	                    const cell = sameLocatorCellsLists[locator].pop();
263	                    if (cell) {
264	                        cell.ordinal = categories.length;
265	                        const val = cell.option.value;
266	                        categories.push(val);
267	                        _cells.push(cell);
268	                        self._uniqueValueGen.calcDupBase(val);
269	                    }
270	                }
271	            }
272	            self._uniqueValueGen.ensureValueUnique(categories, _cells);
273	
274	            const ordinalMeta = self._ordinalMeta = new OrdinalMeta({
275	                categories: categories,
276	                needCollect: false,
277	                deduplication: false,
278	            });
279	            self._scale = new Ordinal({ordinalMeta});
280	
281	            for (let idx = 0; idx < self._leavesCount; idx++) {
282	                const leaf = self._cells[idx];
283	                leaf.type = MatrixCellLayoutInfoType.leaf;
284	                // Handle the tree level variation: enlarge the span of the leaves to reach the body cells.
285	                leaf.span[XY[1 - self.dimIdx]] = self._levels.length - leaf.level;
286	            }
287	
288	            self._initCellsId();
289	            self._initLevelIdOptions();
290	        }
291	    }
292	
293	    private _initBySeriesData() {
294	        const self = this;
295	        self._leavesCount = 0;
296	        self._levels = [{
297	            type: MatrixCellLayoutInfoType.level,
298	            xy: NaN, wh: NaN, option: null, id: new Point(), dim: self
299	        }];
300	        self._initLevelIdOptions();
301	
302	        const ordinalMeta = self._ordinalMeta = new OrdinalMeta({
303	            needCollect: true,
304	            deduplication: true,
305	            onCollect: (value: unknown, ordinalNumber: number): void => {
306	                const cell = self._cells[ordinalNumber] = {
307	                    type: MatrixCellLayoutInfoType.leaf,
308	                    ordinal: ordinalNumber,
309	                    level: 0,
310	                    firstLeafLocator: ordinalNumber,
311	                    id: new Point(), // Set it in `_initCellsId`.
312	                    span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
313	                    // Theoretically `value` is from `dataset` or `series.data`, so it may be any type.
314	                    // Do not restrict this case for user's convenience, and here simply convert it to
315	                    // string for display.
316	                    option: {value: value + ''},
317	                    xy: NaN,
318	                    wh: NaN,
319	                    dim: self,
320	                    rect: createNaNRectLike(),
321	                };
322	                self._leavesCount++;
323	                self._setCellId(cell);
324	            },
325	        });
326	        self._scale = new Ordinal({ordinalMeta});
327	    }
328	
329	    private _setCellId(cell: MatrixDimensionCell) {
330	        const levelsLen = this._levels.length;
331	        const dimIdx = this.dimIdx;
332	        setDimXYValue(cell.id, dimIdx, cell.firstLeafLocator, cell.level - levelsLen);
333	    }
334	
335	    private _initCellsId() {
336	        const levelsLen = this._levels.length;
337	        const dimIdx = this.dimIdx;
338	        each(this._cells, cell => {
339	            setDimXYValue(cell.id, dimIdx, cell.firstLeafLocator, cell.level - levelsLen);
340	        });
341	    }
342	
343	    private _initLevelIdOptions() {
344	        const levelsLen = this._levels.length;
345	        const dimIdx = this.dimIdx;
346	        let levelOptionList = this._model.get('levels', true);
347	        levelOptionList = isArray(levelOptionList) ? levelOptionList : [];
348	
349	        each(this._levels, (levelCfg, level) => {
350	            setDimXYValue(levelCfg.id, dimIdx, 0, level - levelsLen);
351	            levelCfg.option = levelOptionList[level];
352	        });
353	    }
354	
355	    shouldShow(): boolean {
356	        return !!this._model.getShallow('show', true);
357	    }
358	
359	    /**
360	     * Iterate leaves (they are layout units) if dimIdx === this.dimIdx.
361	     * Iterate levels if dimIdx !== this.dimIdx.
362	     */
363	    resetLayoutIterator(
364	        it: ListIterator<MatrixCellLayoutInfo> | NullUndefined,
365	        dimIdx: number,
366	        startLocator?: MatrixXYLocator | NullUndefined,
367	        count?: number | NullUndefined,
368	    ): ListIterator<MatrixCellLayoutInfo> {
369	        it = it || new ListIterator<MatrixCellLayoutInfo>();
370	        if (dimIdx === this.dimIdx) {
371	            const len = this._leavesCount;
372	            const startIdx = startLocator != null ? Math.max(0, startLocator) : 0;
373	            count = count != null ? Math.min(count, len) : len;
374	            it.reset(this._cells, startIdx, startIdx + count);
375	        }
376	        else {
377	            const len = this._levels.length;
378	            // Corner locator is from `-this._levels.length` to `-1`.
379	            const startIdx = startLocator != null ? Math.max(0, startLocator + len) : 0;
380	            count = count != null ? Math.min(count, len) : len;
381	            it.reset(this._levels, startIdx, startIdx + count);
382	        }
383	        return it;
384	    }
385	
386	    resetCellIterator(
387	        it?: ListIterator<MatrixDimensionCell>
388	    ): ListIterator<MatrixDimensionCell> {
389	        return (it || new ListIterator<MatrixDimensionCell>()).reset(this._cells, 0);
390	    }
391	
392	    resetLevelIterator(
393	        it?: ListIterator<MatrixDimensionLevelInfo>
394	    ): ListIterator<MatrixDimensionLevelInfo> {
395	        return (it || new ListIterator<MatrixDimensionLevelInfo>()).reset(this._levels, 0);
396	    }
397	
398	    getLayout(outRect: RectLike, dimIdx: number, locator: MatrixXYLocator): void {
399	        const layout = this.getUnitLayoutInfo(dimIdx, locator);
400	        outRect[XY[dimIdx]] = layout ? layout.xy : NaN;
401	        outRect[WH[dimIdx]] = layout ? layout.wh : NaN;
402	    }
403	
404	    /**
405	     * Get leaf cell or get level info.
406	     * Should be able to return null/undefined if not found on x or y, thus input `dimIdx` is needed.
407	     */
408	    getUnitLayoutInfo(dimIdx: number, locator: MatrixXYLocator): MatrixCellLayoutInfo | NullUndefined {
409	        return dimIdx === this.dimIdx
410	            ? (locator < this._leavesCount ? this._cells[locator] : undefined)
411	            : this._levels[locator + this._levels.length];
412	    }
413	
414	    /**
415	     * Get dimension cell by data, including leaves and non-leaves.
416	     */
417	    getCell(value: MatrixCoordValueOption): MatrixDimensionCell | NullUndefined {
418	        const ordinal = this._scale.parse(value);
419	        return eqNaN(ordinal) ? undefined : this._cells[ordinal];
420	    }
421	
422	    /**
423	     * Get leaf count or get level count.
424	     */
425	    getLocatorCount(dimIdx: number): number {
426	        return dimIdx === this.dimIdx ? this._leavesCount : this._levels.length;
427	    }
428	
429	    getOrdinalMeta(): OrdinalMeta {
430	        return this._ordinalMeta;
431	    }
432	
433	}
434	
435	function createUniqueValueGenerator(dim: 'x' | 'y') {
436	    const dimUpper = dim.toUpperCase();
437	    const defaultValReg = new RegExp(`^${dimUpper}([0-9]+)$`);
438	    let dupBase = 0;
439	
440	    function calcDupBase(val: string | NullUndefined): void {
441	        let matchResult;
442	        if (val != null && (matchResult = val.match(defaultValReg))) {
443	            dupBase = mathMax(dupBase, +matchResult[1] + 1);
444	        }
445	    }
446	
447	    function makeUniqueValue(): string {
448	        return `${dimUpper}${dupBase++}`;
449	    }
450	
451	    // Duplicated value is allowed, because the `matrix.x/y.data` can be a tree and it's reasonable
452	    // that leaves in different subtrees has the same text. But only the first one is allowed to be
453	    // queried by the text, and the other ones can only be queried by index.
454	    // Additionally, `matrix.x/y.data: [null, null, ...]` is allowed.
455	    function ensureValueUnique(categories: (string | NullUndefined)[], cells: MatrixDimensionCell[]): void {
456	        // A simple way to deduplicate or handle illegal or not specified values to avoid unexpected behaviors.
457	        // The tree structure should not be broken even if duplicated.
458	        const cateMap = createHashMap<true, string>();
459	        for (let idx = 0; idx < categories.length; idx++) {
460	            let value = categories[idx];
461	            // value may be set to NullUndefined by users or if illegal.
462	            if (value == null || cateMap.get(value) != null) {
463	                // Still display the original option.value if duplicated, but loose the ability to query by text.
464	                categories[idx] = value = makeUniqueValue();
465	                cells[idx].option = defaults({value}, cells[idx].option);
466	            }
467	            cateMap.set(value, true);
468	        }
469	    }
470	
471	    return {calcDupBase, ensureValueUnique};
472	}
