    /**
     * `matrix.x/y.length: 3` is equivalent to `matrix.x/y.data: [null, null, null]`.
     * Return `NullUndefined` if `lengthOption` is not specified or illegal.
     */
    private _createDimModelDataByLength(
        lengthOption: number | NullUndefined
    ): MatrixDimensionCellLooseOption[] | NullUndefined {
        if (lengthOption == null) {
            return;
        }
        const len = isNumber(lengthOption) && isFinite(lengthOption)
            ? Math.round(lengthOption) : NaN;
        if (eqNaN(len) || len < 0) {
            if (__DEV__) {
                error(`Illegal echarts option - matrix.${this.dim}.length`
                    + ' must be a non-negative number if specified.'
                );
            }
            return;
        }
        const dimModelData: MatrixDimensionCellLooseOption[] = [];
        // Must fill explicitly - a sparse array (e.g. `new Array(len)`) would be skipped
        // by `each`, which delegates to the native `Array#forEach` (holes are ignored).
        for (let idx = 0; idx < len; idx++) {
            dimModelData.push(null);
        }
        return dimModelData;
    }
```
CRITICAL detail: do NOT write `new Array(len)` or rely on holes. `zrender/src/core/util.ts` `each` (lines 294-319) uses `arr.forEach === nativeForEach` and delegates to native `forEach`, which skips array holes — a sparse array would produce zero cells. `isFinite` is already used elsewhere in the repo (`src/util/number.ts:236`), so it is acceptable under the ES3 target. Keep every line <= 120 chars (`max-len` in `/workspace/.eslintrc-common.yaml:174`).
